import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  interpolate,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadBebasNeue = makeLoadFont('BebasNeue');
const loadInter = makeLoadFont('Inter');

const { fontFamily: bebasNeueFamily } = loadBebasNeue();
const { fontFamily: interFamily } = loadInter();



export type LowerThirdProps = Record<string, any>;

const LowerThird: React.FC<LowerThirdProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 14,
  labelColor = "#9A9A9A",
  headlineColor = "#000000",
  steps = [
    { label: "STEP 01", headline: "LIFE BEFORE JESUS" },
    { label: "STEP 02", headline: "ENCOUNTERING JESUS" },
    { label: "STEP 03", headline: "LIFE NOW" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, height } = useVideoConfig();

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  if (!steps || steps.length === 0) {
    return null;
  }

  const totalFrames = durationInSeconds * fps;
  const N = steps.length;
  
  // Safe bounds calculation to avoid math errors if duration is extremely short
  const maxOverlap = Math.floor(totalFrames / (N + 1));
  const overlapFrames = Math.min(Math.round(0.3 * fps), maxOverlap);
  
  // Compute exactly how long each step lives to fill the full duration while preserving overlap
  const stepDuration = (totalFrames + (N - 1) * overlapFrames) / N;
  
  const maxFadeIn = Math.floor(stepDuration / 2);
  const fadeInFrames = Math.min(Math.round(0.5 * fps), maxFadeIn);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {steps.map((step, i) => {
        const startFrame = i * (stepDuration - overlapFrames);
        const endFrame = startFrame + stepDuration;
        const localFrame = frame - startFrame;

        // Render optimization: skip if the step is completely out of its time window
        if (frame < startFrame || frame > endFrame) {
          return null;
        }

        const fadeIn = interpolate(localFrame, [0, fadeInFrames], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.ease),
        });

        const fadeOut = interpolate(
          localFrame,
          [stepDuration - overlapFrames, stepDuration],
          [1, 0],
          {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: Easing.in(Easing.ease),
          }
        );

        // Multiplication inherently maps the complete visual lifetime curve
        const opacity = fadeIn * fadeOut;

        const translateY = interpolate(localFrame, [0, fadeInFrames], [6, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.ease),
        });

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              bottom: height * 0.15, // Anchored to lower-center
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              opacity,
              transform: `translateY(${translateY}px)`,
              transition: "none",
            }}
          >
            <span
              style={{
                fontFamily: interFamily,
                color: labelColor,
                fontSize: "24px",
                fontWeight: "normal",
                textTransform: "uppercase",
                letterSpacing: "0.15em",
                marginBottom: "8px",
                whiteSpace: "nowrap",
                transition: "none",
              }}
            >
              {step.label}
            </span>
            <span
              style={{
                fontFamily: bebasNeueFamily,
                color: headlineColor,
                fontSize: "96px",
                fontWeight: "bold",
                lineHeight: 1,
                letterSpacing: "0.02em",
                whiteSpace: "nowrap",
                transition: "none",
              }}
            >
              {step.headline}
            </span>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default LowerThird;